package com.app.service;
import com.app.entity.*;import com.app.repository.*;import lombok.RequiredArgsConstructor;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.*;import java.util.*;
@Service @RequiredArgsConstructor public class SocietyOperationsEscalationService {private final AccountRepository accounts;private final AccountUserMembershipRepository memberships;private final SocietyStaffAccessRepository staffAccess;private final SocietyWorkOrderRepository workOrders;private final SocietyInspectionRepository inspections;private final SocietyDailyReportRepository reports;private final SocietyNotificationRepository notifications;
 @Scheduled(cron="${app.society.operations-escalation-cron:0 0/30 * * * *}") @Transactional public void generate(){LocalDate today=LocalDate.now();LocalDateTime now=LocalDateTime.now(),end=today.plusDays(1).atStartOfDay();for(Account a:accounts.findByAccountTypeAndActiveTrueOrderByAccountNameAsc(AccountType.SOCIETY)){for(User u:recipients(a)){for(SocietyWorkOrder w:workOrders.findByAccountIdOrderByCreatedAtDesc(a.getId()))if(w.getDueAt()!=null&&w.getDueAt().isBefore(now)&&!Set.of("COMPLETED","VERIFIED","CANCELLED").contains(w.getStatus()))ensure(a,u,"WORK_ORDER_OVERDUE","AUTO:WO:"+w.getId()+":"+today,"WORK_ORDER",w.getId(),"Work order overdue",w.getWorkOrderNumber()+" · "+w.getTitle()+" is overdue",Set.of("HIGH","EMERGENCY").contains(w.getPriority())?w.getPriority():"HIGH");for(SocietyInspection x:inspections.findByAccountIdOrderByScheduledForDesc(a.getId()))if("PENDING".equals(x.getResult())&&x.getScheduledFor()!=null&&x.getScheduledFor().isBefore(end))ensure(a,u,"INSPECTION_DUE","AUTO:INSPECTION:"+x.getId()+":"+today,"INSPECTION",x.getId(),"Inspection due",x.getTitle()+" is due",x.getScheduledFor().isBefore(now)?"HIGH":"NORMAL");if(now.getHour()>=18&&reports.findByAccountIdAndReportDateOrderByRevisionDesc(a.getId(),today).stream().noneMatch(x->Set.of("SUBMITTED","ACKNOWLEDGED").contains(x.getStatus())))ensure(a,u,"DAILY_REPORT_MISSING","AUTO:REPORT:"+today,"DAILY_REPORT",a.getId(),"Daily report pending","Today's supervisor operations report has not been submitted","HIGH");}}}
 private Set<User> recipients(Account a){Set<User> result=new LinkedHashSet<>();result.add(a.getUser());memberships.findByAccountIdAndActiveTrueOrderByCreatedAtAsc(a.getId()).stream().filter(x->Set.of(UserRole.ADMIN,UserRole.SUPERVISOR).contains(x.getRole())).forEach(x->result.add(x.getUser()));staffAccess.findAll().stream().filter(x->x.getAccount().getId().equals(a.getId())&&x.getStatus()==StaffAccessStatus.ACTIVE).forEach(x->result.add(x.getUser()));return result;}
 private void ensure(Account a,User u,String type,String key,String entityType,Long entityId,String title,String message,String priority){if(notifications.findByAccountIdAndRecipientIdAndDedupeKey(a.getId(),u.getId(),key).isPresent())return;notifications.save(SocietyNotification.builder().account(a).recipient(u).notificationType(type).entityType(entityType).entityId(entityId).dedupeKey(key).title(title).message(message).priority(priority).build());}
}
